// Package licenses prints Recarto's licence and the notices of the third-party
// code compiled or embedded into its binary. modules.txt is generated by
// `go run ./tools/licenses`; see CONTRIBUTING.md.
package licenses

import (
	_ "embed"
	"io"
	"runtime"
	"strings"

	"github.com/gerwim/recarto"
	"github.com/gerwim/recarto/internal/embedding"
	"github.com/gerwim/recarto/internal/version"
)

// Notice is one component's licence notice.
type Notice struct {
	Name    string // module path or component name
	Version string // empty when the component has none
	License string // SPDX licence expression
	Texts   []Text
}

// Text is one licence, copyright or NOTICE file of a component.
type Text struct {
	Path string // relative to the component's root, slash-separated
	Body string
}

//go:embed modules.txt
var modules string

//go:embed texts/go/LICENSE
var goLicense string

//go:embed texts/musl/COPYRIGHT
var muslLicense string

//go:embed texts/mingw-w64/COPYING
var mingwLicense string

//go:embed texts/zig/LICENSE
var zigLicense string

// Zig compiler-rt is linked into every release binary by `zig cc`.
const zigVersion = "0.13.0"

// Render returns n in the format `recarto licenses` prints.
func (n Notice) Render() string {
	const rule = "--------------------------------------------------------------------------------\n"
	var b strings.Builder
	b.WriteString(rule)
	b.WriteString(n.Name)
	if n.Version != "" {
		b.WriteString(" " + n.Version)
	}
	b.WriteString("\nLicense: " + n.License + "\n")
	b.WriteString(rule)
	for _, t := range n.Texts {
		b.WriteString("\n" + t.Path + ":\n\n" + strings.TrimSpace(t.Body) + "\n")
	}
	b.WriteString("\n")
	return b.String()
}

// Write writes Recarto's licence, then the notice of every third-party component.
func Write(w io.Writer) error {
	var b strings.Builder
	b.WriteString(Notice{
		Name:    "Recarto",
		Version: version.Version,
		License: "MIT",
		Texts:   []Text{{Path: "LICENSE", Body: recarto.License}},
	}.Render())
	b.WriteString("\nThird-party notices\n\nThe recarto binary contains the components below. Some are only in the binary for one platform.\n\n")
	for _, n := range []Notice{
		{Name: "Go standard library and runtime", Version: runtime.Version(), License: "BSD-3-Clause", Texts: []Text{{Path: "LICENSE", Body: goLicense}}},
		{Name: "musl libc", Version: "1.2.5", License: "MIT", Texts: []Text{{Path: "COPYRIGHT", Body: muslLicense}}},
		{Name: "MinGW-w64 runtime", Version: "12.0.0", License: "ZPL-2.1 (parts: public domain, BSD, LGPL; see COPYING)", Texts: []Text{{Path: "COPYING", Body: mingwLicense}}},
		{Name: "Zig compiler-rt", Version: zigVersion, License: "MIT", Texts: []Text{{Path: "LICENSE", Body: zigLicense}}},
		{Name: "potion-base-8M model (MinishLab)", Version: embedding.Revision, License: "MIT", Texts: []Text{{Path: "LICENSE", Body: embedding.License}}},
	} {
		b.WriteString(n.Render())
	}
	b.WriteString(modules)
	_, err := io.WriteString(w, b.String())
	return err
}
